PROBE SOURCE, FULL AND VERBATIM (global rail 12b) — the standalone production-boot probe behind step 4 / step 5. Run from `apps/daemon` as `node <file>` (add `PROBE_COMMIT=1` for the committed-repo variant). Not committed; the DURABLE discharge of DoD 1 and DoD 3 is the committed arm `apps/daemon/src/daemon-main-activation-boot.test.ts`, and this is here so a grader can recreate and re-run the exact transcript quoted in the step notes.

```js
// Standalone production-boot probe for /activation/read. Runs with cwd = apps/daemon.
import { spawn } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, realpathSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { request as httpRequest } from "node:http";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const ROOT = process.cwd();
const { WIRE_PROTOCOL_VERSION } =
  await import(pathToFileURL(resolve(ROOT, "src/http/http-contract.ts")).href);

const CSRF = "probe-csrf";
const CREDENTIAL = "probe-operator-credential";
const scratch = realpathSync(mkdtempSync(join(tmpdir(), "moe-activation-probe-")));
const projectRoot = join(scratch, "project");
// A REAL, EXISTING project root: execFile("git", ...) ENOENTs on a MISSING cwd, which would
// leave repository/distribution unmeasured for a reason unrelated to the wiring under test.
const override = process.argv[2];
if (override === undefined) {
  mkdirSync(projectRoot, { recursive: true });
  execFileSync("git", ["init", "--quiet"], { cwd: projectRoot, stdio: "ignore" });
  if (process.env.PROBE_COMMIT === "1") {
    const g = (...a) => execFileSync("git", a, { cwd: projectRoot, stdio: "ignore" });
    g("config", "user.email", "probe@example.invalid");
    g("config", "user.name", "probe");
    writeFileSync(join(projectRoot, "README.md"), "probe");
    g("add", "README.md");
    g("commit", "--quiet", "-m", "probe");
  }
}
const effectiveRoot = override ?? projectRoot;

const child = spawn(process.execPath, [
  resolve(ROOT, "src/daemon-main.ts"),
  "--dependencies=./src/daemon-store-dependencies.ts",
  "--port=0",
  `--csrf-token=${CSRF}`,
], {
  cwd: ROOT,
  env: {
    ...process.env,
    MOE_DAEMON_CREDENTIAL: CREDENTIAL,
    MOE_PROJECT_ID: "proj-activation-probe",
    MOE_PROJECT_ROOT: effectiveRoot,
    MOE_STORE_PATH: join(scratch, "store.db"),
  },
  shell: false,
  windowsHide: true,
});

const where = await new Promise((res, rej) => {
  let transcript = "";
  child.stdout.setEncoding("utf8");
  child.stdout.on("data", (c) => {
    transcript += c;
    const m = /listening on (http:\/\/127\.0\.0\.1:(\d+))/u.exec(transcript);
    if (m) res({ origin: m[1], port: Number(m[2]) });
  });
  child.stderr.setEncoding("utf8");
  child.stderr.on("data", (c) => { transcript += c; });
  child.on("exit", (code) => rej(new Error(`exited ${code}\n${transcript}`)));
});

function post(path, payload, credential = CREDENTIAL) {
  return new Promise((res, rej) => {
    const req = httpRequest({
      headers: {
        "content-length": Buffer.byteLength(payload), "content-type": "application/json",
        host: `127.0.0.1:${where.port}`, origin: where.origin,
        "x-moe-csrf": CSRF, "x-moe-protocol-version": WIRE_PROTOCOL_VERSION,
        "x-moe-session-credential": credential,
      },
      host: "127.0.0.1", method: "POST", path, port: where.port, setHost: false,
    }, (r) => {
      const chunks = [];
      r.on("data", (c) => chunks.push(c));
      r.on("end", () => res({
        status: r.statusCode, body: JSON.parse(Buffer.concat(chunks).toString("utf8")),
      }));
    });
    req.on("error", rej);
    req.end(payload);
  });
}

const backups = join(effectiveRoot, ".moe-next", "backups");
console.log("origin:", where.origin);
console.log("projectRoot:", effectiveRoot);
console.log("backupsDirBeforeReads:", existsSync(backups));

const first = await post("/activation/read", "{}");
console.log("=== POST /activation/read (read 1 of 3) ===");
console.log("HTTP", first.status);
console.log(JSON.stringify(first.body, null, 2));

await post("/activation/read", "{}");
await post("/activation/read", "{}");
console.log("=== after 3 reads ===");
console.log("backupsDirAfter3Reads:", existsSync(backups));
console.log("projectRootExists:", existsSync(effectiveRoot));
console.log("moeNextDirExists:", existsSync(join(effectiveRoot, ".moe-next")));

child.kill();
```
